"""Additional aggregate tables, numbered after the stable S1–S36 sequence."""
import pandas as pd
import numpy as np

def extend_tables(tables,spec,show,read,names):
    cross=pd.DataFrame([
        ['Outcome and risk set','5a–b, 6b, 8a, 11','Participants/data; outcome','Stop if absent follow-up is an exit, current routing conflicts with state, or wave-27 censoring enters eligible attrition.'],
        ['Availability and OOF','9b, 12a–c','Predictors; analysis','Stop if an OOF training label reaches its scoring wave; declare batch boundaries and separately test strict embargo.'],
        ['Fit provenance','7, 12b–c, 12g, 13','Predictors; analysis','Stop if preprocessing uses later records, objectives differ silently, or reported scores/SHAP use different fitted objects.'],
        ['Calibration and decisions','12e–f, 15','Analysis','Stop if test outcomes select calibration or thresholds; freeze maps and report raw outputs separately.'],
        ['Dependence and transport','12d–e, 14, 16, 23a','Participants/data; analysis','Stop if paired inference splits respondent histories; report period, cohort and subgroup scope alongside fit-conditional intervals.'],
        ['Reproduction','18e–f','All domains','Stop if sample identities, checksums or table arithmetic fail; expose code and source-to-feature mappings.']
    ],columns=['Protocol step','TRIPOD+AI items','PROBAST+AI domains','Executable panel-specific requirement'])
    spec('framework_crosswalk','Relationship to established reporting and appraisal frameworks',cross,'Collins et al. (2024); Moons et al. (2025); protocol.json','Item numbers refer to TRIPOD+AI. PROBAST+AI separately addresses development quality and evaluation risk of bias; the shared domains are mapped here. This is a scope crosswalk, not a completed risk-of-bias rating or a claim of new statistical estimators.')
    variation=read('feature_variation.csv');variation=variation[variation.constant_in_primary_training.eq(True)];rr=[]
    for f,g in variation.groupby('feature',sort=False):
        row={'Feature':f}
        for part in ['train','validation','test']:
            z=g[g.partition.eq(part)].iloc[0];row[part.title()+' distinct / range']=f'{int(z.distinct_nonmissing)} / {z.minimum:g}–{z.maximum:g}'
        rr.append(row)
    spec('period_variation','Eligible calendar flags with zero training variation',pd.DataFrame(rr),'feature_variation.csv','All flags use baseline survey year: workweek flag ≥2018; COVID flag 2020–2021; post-COVID flag ≥2022. Coverage eligibility does not imply learnable variation. All other retained primary inputs vary in training.')
    ds=read('drift_standardization.csv');z=pd.DataFrame({'Partition':ds.partition.str.capitalize(),'N':ds.n.map(lambda x:f'{int(x):,}'),'Mean age':ds.mean_age.map(lambda x:f'{x:.1f}'),'2018 share':ds.share_2018_cohort.map(lambda x:f'{100*x:.2f}%'),'Raw rate':ds.raw_event_rate.map(lambda x:f'{100*x:.2f}%'),'Common coverage':ds.common_support_coverage.map(lambda x:f'{100*x:.2f}%'),'Standardised rate [95% CI]':ds.apply(lambda r:f'{100*r.standardized_event_rate:.2f}% [{100*r.standardized_lower:.2f}, {100*r.standardized_upper:.2f}]',axis=1)})
    spec('drift_standardized','Age–cohort standardisation on shared support',z,'drift_standardization.csv; drift_strata.csv','Denominators are outcome-observed analysis rows, rather than all eligible baselines. Shared support excludes the 2018 addition. Reference weights are the pooled common-support person-wave proportions, held fixed during 500 paired person-cluster bootstrap draws. Rates describe the shared-support population, not an extrapolation to absent historical cells.')
    dc=read('drift_decomposition.csv');labels={'total_event_rate_change':'Total change','age_cohort_composition_common_support':'Composition on shared support','within_stratum_rate_change_common_support':'Within-stratum rate change','outside_common_support_contribution':'Outside-support contribution'};z=pd.DataFrame({'Period contrast':dc.from_partition.str.capitalize()+' → '+dc.to_partition.str.capitalize(),'Component':dc.component.map(labels),'Change, percentage points':dc.estimate.map(lambda x:f'{100*x:+.3f}'),'95% interval':dc.apply(lambda r:f'[{100*r.lower:+.3f}, {100*r.upper:+.3f}]',axis=1)})
    spec('drift_decomposition','Exact descriptive decomposition of prevalence changes',z,'drift_decomposition.csv','On shared support, composition = Σ(pB−pA)(rA+rB)/2 and rate change = Σ(rB−rA)(pA+pB)/2. Outside-support contribution = (RB−RB_common)−(RA−RA_common). These three terms sum to the full change. No causal attribution is implied; intervals use 500 paired person draws.')
    oc=read('origin_contrasts.csv');oc=oc[((oc.model_A=='catboost')&(oc.model_B=='forward_stack'))|((oc.model_A=='random_forest')&oc.model_B.isin(['catboost','forward_stack']))].copy();oc['model_A']=oc.model_A.map(names);oc['model_B']=oc.model_B.map(names)
    spec('origin_contrasts','Paired earlier-origin comparisons of the leading learners',show(oc,['train_end','model_A','model_B','metric','difference_A_minus_B','lower','upper'],{'model_A':'A','model_B':'B','difference_A_minus_B':'A − B'}),'origin_contrasts.csv','Raw scores; 500 paired person-cluster draws within each origin. All five-model contrasts and marginal intervals are supplied in the CSVs. These origins share respondents and are not independent replications.')
    sm=read('seed_summary.csv');sm=sm[sm.model.isin(['catboost','forward_stack'])];z=[]
    for _,r in sm.iterrows():z.append([names[r.model],r.method.capitalize(),f'{r.roc_auc_mean:.4f} ({r.roc_auc_std:.4f})',f'{r.roc_auc_min:.4f}–{r.roc_auc_max:.4f}',f'{r.brier_mean:.5f} ({r.brier_std:.5f})',f'{r.brier_min:.5f}–{r.brier_max:.5f}'])
    spec('seed_summary','Ten-seed distributions for CatBoost and forward stacking',pd.DataFrame(z,columns=['Model','Output','ROC-AUC mean (SD)','ROC-AUC range','Brier mean (SD)','Brier range']),'seed_metrics.csv; seed_summary.csv','Seeds 20261026–20261035. Every stochastic full-training and forward-OOF base fit is repeated; deterministic logistic predictions are reused. Meta fits, maps and thresholds are re-estimated. SD and ranges describe algorithmic randomness on fixed data, not sampling confidence intervals.')
    sc=read('seed_contrasts.csv');sc=sc[sc.method.eq('raw')&sc.metric.isin(['roc_auc','pr_auc','brier'])].copy();label={'forward_stack':'Forward stack','catboost':'CatBoost','no_year':'No year','no_calendar':'No calendar','no_constant_period_flags':'No constant flags'};z=pd.DataFrame({'Contrast A − B':sc.model_A.map(label)+' − '+sc.model_B.map(label),'Metric':sc.metric.map({'roc_auc':'ROC-AUC','pr_auc':'PR-AUC','brier':'Brier'}),'Mean':sc.mean_A_minus_B.map(lambda x:f'{x:+.6f}'),'SD':sc.sd_A_minus_B.map(lambda x:f'{x:.6f}'),'Range':sc.apply(lambda r:f'{r.minimum:+.6f} to {r.maximum:+.6f}',axis=1),'Positive / 10':sc.positive_differences.astype(int).astype(str)})
    spec('seed_contrasts','Paired ten-seed model and calendar contrasts',z,'seed_contrasts.csv','Raw outputs. Positive AUC/AP differences favour A; negative Brier differences favour A. Matching seeds pairs experiments but feature deletion may change implementation indexing and random draws. Full recalibrated contrasts are in the CSV.')
    lg=read('logit_stack.csv');pm=read('model_calibration_metrics.csv');pm=pm[pm.partition.eq('test')&pm.model.eq('forward_stack')].copy();pm['model']='Probability inputs';lg['model']='Logit inputs'
    z=show(pd.concat([pm,lg]),['model','method','roc_auc','pr_auc','brier','calibration_intercept','calibration_slope'])
    pairs=read('logit_stack_contrasts.csv');pairs=pairs[pairs.model_A.eq('forward_stack')&pairs.model_B.eq('logit_input_stack')].set_index('metric')
    contrast=['Logit − probability','Raw Δ']
    for metric in ['roc_auc','pr_auc','brier']:
        r=pairs.loc[metric];contrast.append(f'{-r.difference_A_minus_B:+.6f}\n[{-r.upper:+.6f}, {-r.lower:+.6f}]')
    contrast+=['—','—'];z=pd.concat([z,pd.DataFrame([contrast],columns=z.columns)],ignore_index=True)
    spec('logit_stack','Meta-input scale sensitivity',z,'logit_stack.csv; model_calibration_metrics.csv; logit_stack_contrasts.csv','Same base probabilities, OOF rows and C=1; logits are clipped at 10⁻⁶ without further standardisation. Maps use validation data. The final row is the raw logit-minus-probability-input difference [95% interval] from 500 paired person-cluster draws with fixed fits. Positive AUC/AP and negative Brier differences favour logit inputs; dashes mark uncomputed CITL/slope contrasts. This post hoc sensitivity retains the probability-input stack as primary.')
    lt=read('stack_lower_tail.csv');lt['variant']=lt.variant.str.replace('_',' ').str.capitalize();spec('stack_lower_tail','Low-score behaviour of the two meta-input scales',show(lt,['variant','minimum_probability','lower_decile_n','lower_decile_mean_prediction','lower_decile_observed_rate'],{'variant':'Variant','minimum_probability':'Minimum p','lower_decile_n':'Lower group N','lower_decile_mean_prediction':'Mean p','lower_decile_observed_rate':'Observed rate'}),'stack_lower_tail.csv','The lower group includes every score at or below its 10th percentile; ties can make it exceed 10% of rows. The primary positive meta-coefficients impose a theoretical floor sigmoid(intercept), recorded in stack_floor.json.')
    ac=read('matched_below65_contrasts.csv');ac=ac[(ac.model_A=='catboost')&(ac.model_B=='under65_refit')].set_index('metric')
    age=read('matched_below65.csv');spec('matched_below65','Same-test-sample comparison below age 65',show(age,['fit_population','model','method','roc_auc','pr_auc','brier','recall','positive_rate'],{'fit_population':'Training ages','positive_rate':'Selected'}),'matched_below65.csv; matched_below65_contrasts.csv',f'Every row evaluates the same 22,987 below-65 test baselines with 1,713 events. All-age fits use the primary validation operating point; the age-restricted refit uses its restricted validation window. Raw comparisons hold the test population fixed. The all-age-minus-restricted raw AUC contrast is {ac.loc["roc_auc","difference_A_minus_B"]:+.6f} with a 500-draw paired person interval [{ac.loc["roc_auc","lower"]:+.6f}, {ac.loc["roc_auc","upper"]:+.6f}]; the Brier contrast is {ac.loc["brier","difference_A_minus_B"]:+.6f} [{ac.loc["brier","lower"]:+.6f}, {ac.loc["brier","upper"]:+.6f}].')
    dj=read('disjoint_history_groups.csv');dj=dj[dj.history_definition.isin(['all','eligible_training_history'])].copy()
    def group_label(r):
        arm='Training arm' if r.arm=='training' else 'Held-out arm'
        return arm+', all' if r.history_definition=='all' else arm+(', with history' if r.history else ', without history')
    dj['evaluation_group']=dj.apply(group_label,axis=1)
    co=read('disjoint_history_contrasts.csv');co=co[co.history_definition.eq('eligible_training_history')&co.method.eq('raw')&co.metric.eq('roc_auc')].set_index('contrast')
    h=co.loc['eligible_or_observed_history'];n=co.loc['without_history'];delta=co.loc['history_minus_no_history_gap']
    note=f'History = at least one labelled wage-employed baseline at waves 1–20. Training-minus-held-out AUC [95% CI]: with history {h.estimate:+.4f} [{h.lower:+.4f}, {h.upper:+.4f}]; without history {n.estimate:+.4f} [{n.lower:+.4f}, {n.upper:+.4f}]; difference between gaps {delta.estimate:+.4f} [{delta.lower:+.4f}, {delta.upper:+.4f}]. Intervals use 500 person draws within four cells, with one fixed model and map. Alternative interview-history results are in the companion CSVs.'
    spec('disjoint_groups','Same disjoint model by assignment and prior training eligibility',show(dj,['evaluation_group','method','n','people','events','roc_auc','pr_auc','brier'],{'evaluation_group':'Test-window group','people':'People'}),'disjoint_history_groups.csv; disjoint_history_contrasts.csv; disjoint_history_design.json',note)
    hh=read('household_component_contrasts.csv');hh=hh[((hh.model_A=='catboost')&(hh.model_B=='forward_stack'))|((hh.model_A=='catboost_platt')&(hh.model_B=='forward_stack_platt'))].copy();hh['model_A']=hh.model_A.map({'catboost':'CatBoost raw','catboost_platt':'CatBoost Platt'});hh['model_B']=hh.model_B.map({'forward_stack':'Stack raw','forward_stack_platt':'Stack Platt'});spec('household_contrasts','Household-component paired uncertainty sensitivity',show(hh,['model_A','model_B','metric','difference_A_minus_B','lower','upper'],{'model_A':'A','model_B':'B','difference_A_minus_B':'A − B'}),'household_component_contrasts.csv','1,000 connected-component resamples. Components link people co-resident within any same test wave and preserve all rows of movers. This addresses additional observed household dependence, not the full complex sampling design.')
    th=read('calibration_raw_thresholds.csv');th['calibration_window']=th.calibration_window.map({'all_21_23':'21–23','pre2020_21_22':'21–22','2020_only_23':'23'});spec('raw_thresholds','Validation-selected cutoffs expressed on the raw probability scale',show(th,['calibration_window','model','platt_threshold','raw_equivalent_threshold','test_selected','test_selected_matches_all_window'],{'calibration_window':'Waves','test_selected_matches_all_window':'Same set as 21–23'}),'calibration_raw_thresholds.csv','Each window independently refits Platt and selects an F1 cutoff. Raw cutoff = sigmoid((logit(cutoff)−intercept)/slope). Test sets are compared row by row; raw cutoffs in the same test-score gap can produce identical selections under separately fitted maps.')
